reactExercise.solution:
import React, { useState } from 'react';

export default function App() {
  const [count, setCount] = useState(0);

  const handleIncrement = () => {
    setCount(previous => previous + 1);
  };

  const handleDecrement = () => {
    setCount(previous => previous - 1);
  };

  const handleReset = () => {
    setCount(0);
  };

  return (
    <div style={{ padding: '24px', fontFamily: 'sans-serif', textAlign: 'center' }}>
      <h2>Counter Application</h2>
      <h1 id="counter-value" style={{ fontSize: '48px', margin: '16px 0' }}>
        {count}
      </h1>

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'center' }}>
        <button id="dec-btn" onClick={handleDecrement}>-1</button>
        <button id="reset-btn" onClick={handleReset}>Reset</button>
        <button id="inc-btn" onClick={handleIncrement}>+1</button>
      </div>
    </div>
  );
}

